// Replays proto/testdata/free_credit_vectors.json (generated by
// `cd proto/go && go test ./freecredit -run TestFreeCreditVectors -update`)
// and the static RFC 9474 vector against proto/ts/src/freecredit. If this
// fails, the TS port has drifted from Go — fix the divergence rather than
// regenerating the fixture.

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { RSABSSA } from '@cloudflare/blindrsa-ts'
import { base64, hex } from '@scure/base'
import { beforeAll, describe, expect, it } from 'vitest'

import {
    CODE_CREDITS_EXHAUSTED,
    CODE_EPOCH_NOT_ISSUABLE,
    CODE_FREE_CREDIT_INVALID,
    CODE_FREE_CREDIT_SPENT,
    type Credit,
    DAY_KEY_PATH,
    type DayKey,
    GRACE_MS,
    ISSUE_PATH,
    MAX_ISSUE_BATCH,
    acceptedEpochs,
    blindCredit,
    creditMessage,
    dayKeyCertMessage,
    epochAt,
    epochStartMs,
    parseCredit,
    parseDayKeySPKI,
    parseIssuerKey,
    refusalReason,
    verifyCredit,
    verifyDayKey,
} from '../src/freecredit/index.js'
import { ed25519 } from '../src/util/ed25519.js'

type Json = Record<string, any> // eslint-disable-line @typescript-eslint/no-explicit-any

const here = path.dirname(fileURLToPath(import.meta.url))
const read = (name: string) => JSON.parse(fs.readFileSync(path.resolve(here, '..', '..', 'testdata', name), 'utf8')) as Json
const v = read('free_credit_vectors.json')
const rfc = read('rfc9474_pss_deterministic.json')

const suite = () => RSABSSA.SHA384.PSS.Deterministic({ supportsRSARAW: false })
const issuers: Record<string, Uint8Array> = {
    issuer: parseIssuerKey(v.issuers.issuer.key),
    other: parseIssuerKey(v.issuers.other.key),
}
const node = (c: Json) => ({ op: BigInt(c.operator), node: BigInt(c.node) })

async function verdict(run: () => Promise<unknown>): Promise<string> {
    try {
        await run()
        return ''
    } catch (e) {
        const r = refusalReason(e)
        if (r === '') throw e
        return r
    }
}

// The issuer's half, for the round trip only: this package has no signer.
let daySecret: CryptoKey
let dayKey: DayKey
const dep = hex.decode(v.day_key_cert_message.deployment)
const epoch = v.day_key_cert_message.epoch as number

beforeAll(async () => {
    daySecret = await crypto.subtle.importKey('pkcs8', base64.decode(v.random.day_key_pkcs8), { name: 'RSA-PSS', hash: 'SHA-384' }, true, ['sign'])
    dayKey = await verifyDayKey([issuers.issuer!], dep, JSON.parse(JSON.stringify(v.verify[0].credit)) as Credit)
})

describe('free_credit_vectors.json', () => {
    it('is the schema this test expects', () => {
        expect(v.version).toBe(1)
        expect(v.variant).toBe('RSABSSA-SHA384-PSS-Deterministic')
        expect(v.grace_seconds * 1000).toBe(GRACE_MS)
        for (const section of [v.messages, v.epochs, v.day_key_policy, v.verify]) {
            expect(Array.isArray(section) && section.length > 0).toBe(true)
        }
    })

    it('reads each issuer key as the 32 bytes of its private half', () => {
        for (const name of ['issuer', 'other']) {
            // PKCS#8 Ed25519 is a 16-byte header and the 32-byte seed.
            const seed = base64.decode(v.issuers[name].pkcs8).subarray(16)
            expect(hex.encode(ed25519.getPublicKey(seed))).toBe(hex.encode(issuers[name]!))
        }
        expect(() => parseIssuerKey(base64.encode(new Uint8Array(31)))).toThrow(/32 bytes/)
        expect(() => parseIssuerKey(base64.encode(new Uint8Array(33)))).toThrow(/32 bytes/)
        expect(() => parseIssuerKey(v.issuers.issuer.key.slice(0, 20) + '\n' + v.issuers.issuer.key.slice(20))).toThrow()
    })

    it('spells the issue wire and the node refusal codes as Go does', () => {
        expect({
            day_key_path: DAY_KEY_PATH,
            issue_path: ISSUE_PATH,
            max_issue_batch: MAX_ISSUE_BATCH,
            credits_exhausted: CODE_CREDITS_EXHAUSTED,
            epoch_not_issuable: CODE_EPOCH_NOT_ISSUABLE,
            free_credit_invalid: CODE_FREE_CREDIT_INVALID,
            free_credit_spent: CODE_FREE_CREDIT_SPENT,
        }).toEqual(v.wire)
    })

    it('builds the message bytes Go does', () => {
        for (const c of v.messages) {
            expect(hex.encode(creditMessage(hex.decode(c.deployment), node(c), c.epoch, hex.decode(c.nonce)))).toBe(c.message)
        }
    })

    it('builds the day-key certificate message Go does', () => {
        const c = v.day_key_cert_message
        expect(hex.encode(dayKeyCertMessage(hex.decode(c.deployment), c.epoch, base64.decode(c.day_key)))).toBe(c.message)
    })

    it('puts a time in the epochs Go does', () => {
        for (const c of v.epochs) {
            const ms = Number(c.unix) * 1000
            expect(epochAt(ms)).toBe(c.epoch)
            expect(acceptedEpochs(ms)).toEqual(c.accepted)
        }
        expect(epochAt(-1)).toBe(0)
        expect(epochStartMs(20_753)).toBe(Date.UTC(2026, 9, 27))
    })

    for (const c of v.day_key_policy as Json[]) {
        it(`day key policy: ${c.name}`, async () => {
            const got = await parseDayKeySPKI(base64.decode(c.spki)).then(
                () => true,
                () => false,
            )
            expect(got).toBe(c.ok)
        })
    }

    for (const c of v.verify as Json[]) {
        it(`verify: ${c.name}`, async () => {
            const trusted = (c.issuers as string[]).map((k) => issuers[k]!)
            const got = await verdict(() => verifyCredit(trusted, hex.decode(c.deployment), node(c), c.epochs, parseCredit(c.credit)))
            expect(got).toBe(c.reason)
        })
    }
})

describe('rfc9474_pss_deterministic.json', () => {
    const b = (k: string) => hex.decode(rfc[k])
    const b64u = (k: string) => base64.encode(b(k)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')

    // The same variant check as Go's TestRFC9474Vector, plus the payer's
    // unblinding, which only the TS library lets a caller drive with a fixed
    // factor.
    it('verifies and unblinds as the RFC does', async () => {
        const alg = { name: 'RSA-PSS', hash: 'SHA-384' }
        const pub = await crypto.subtle.importKey('jwk', { kty: 'RSA', n: b64u('n'), e: b64u('e'), ext: true }, alg, true, ['verify'])
        expect(rfc.name).toBe('RSABSSA-SHA384-PSS-Deterministic')
        expect(await suite().verify(pub, b('sig'), b('msg'))).toBe(true)
        expect(hex.encode(await suite().finalize(pub, b('msg'), b('blind_sig'), b('inv')))).toBe(rfc.sig)
    })
})

describe('a credit round trip in TS', () => {
    const n = { op: 12, node: 3 }

    it('blinds, unblinds and verifies a credit under the vectors day key', async () => {
        const { blinded, pending } = await blindCredit(dayKey, dep, n)
        const c = await pending.finalize(await suite().blindSign(daySecret, blinded))
        await verifyCredit([issuers.issuer!], dep, n, [epoch], c)
        expect(c.issuer).toBe(v.issuers.issuer.key)
        expect(c.epoch).toBe(epoch)
    })

    it('refuses to unblind a signature over another message', async () => {
        const a = await blindCredit(dayKey, dep, n)
        const other = await blindCredit(dayKey, dep, n)
        const sig = await suite().blindSign(daySecret, other.blinded)
        expect(await verdict(() => a.pending.finalize(sig))).toBe('bad_signature')
    })

    it('draws a fresh nonce per credit', async () => {
        const a = await blindCredit(dayKey, dep, n)
        const b2 = await blindCredit(dayKey, dep, n)
        const ca = await a.pending.finalize(await suite().blindSign(daySecret, a.blinded))
        const cb = await b2.pending.finalize(await suite().blindSign(daySecret, b2.blinded))
        expect(ca.nonce).not.toBe(cb.nonce)
    })

    it('refuses a certificate from an untrusted issuer', async () => {
        expect(await verdict(() => verifyDayKey([issuers.other!], dep, dayKey.cert))).toBe('unknown_issuer')
    })

    it('reads an absent field as empty, and a mistyped one as malformed', () => {
        expect(parseCredit({}).nonce).toBe('')
        expect(parseCredit({ epoch: null }).epoch).toBe(0)
        for (const bad of [null, [], 'x', { epoch: -1 }, { epoch: 1.5 }, { epoch: '1' }, { epoch: 2 ** 32 }, { nonce: 7 }]) {
            expect(() => parseCredit(bad), JSON.stringify(bad)).toThrow(/malformed/)
        }
    })
})
